    {
     "heading": "擺盪在兩個目標之間：真相與秩序",
     "heading_en": "Torn Between Two Goals: Truth and Order",
     "body": [
      "理解虛構故事的歷史角色之後，哈拉瑞提出一個更完整的資訊網路模型，不必在天真的資訊觀和[[民粹主義資訊觀|populist view of information]]之間二選一。資訊不像天真觀點以為的必然帶來真相，發現真相也不是資訊網路唯一的目的；但資訊也不像民粹觀點說的只是一種武器。每個想要生存與繁榮的資訊網路，都必須同時做到兩件事：**發現真相**，以及**創造秩序**。所以人類網路一直在發展兩套技能。一套如天真觀點所預期，學習如何處理資訊，才能更準確地掌握醫學、猛獁象、核物理。另一套是學習如何運用資訊，在更大的人口中維持更強的秩序：除了真實的陳述，還用上虛構、幻想、宣傳，偶爾也會說徹頭徹尾的謊話。光有大量資訊，既不保證得到真相，也不保證維持秩序；兩個目標本就難以兼顧，還常常互相衝突，因為虛構通常更容易維持秩序。",
      "有時虛構會承認自己是虛構（例如美國憲法），但更多時候會矢口否認。宗教總說自己是客觀而永恆的真理，絕非人類發明。這時光是追求真相，就會威脅社會秩序的基礎，於是許多社會要求人民不要瞭解自己真正的起源：[[無知就是力量|ignorance is strength]]。最明顯的例子是達爾文(Charles Darwin)的演化論。瞭解演化能大幅增進我們對物種（包括智人）起源的認識，卻也動搖了許多社會賴以維繫的核心神話。難怪許多政府和教會禁止或限制演化論教學，寧可選秩序、犧牲真理。"
     ]
    },
    {
     "heading": "真理與秩序如何平衡？強大卻不明智的網路",
     "heading_en": "Balancing Truth and Order: Powerful but Unwise Networks",
     "body": [
      "相關的問題是：資訊網路常常只在「能產生力量、又不威脅秩序」的特定領域鼓勵追求真相，結果可能造出一個力量極大、卻極度缺乏智慧的網路。納粹德國培養出許多世界頂尖的化學、光學、工程與火箭科學專家，美國後來登上月球，大半功勞也要歸給納粹的火箭科學。高超的科學讓納粹打造出可怕的戰爭機器，用來服務一套瘋狂又殘暴的神話。在納粹統治下，德國鼓勵研究火箭科學，對種族主義理論背後的生物學與歷史卻不容質疑。",
      "因此我們不能說，人類資訊網路的歷史是一場[[進步的勝利遊行|triumphal march of progress]]。人類網路一代比一代強大，卻不見得一代比一代明智；把秩序看得比真相重要的網路，可能擁有無比強大的力量，卻拿來做極其愚蠢的事。這段歷史更像一場在真相與秩序之間的[[走鋼索|tightrope walk]]。到了二十一世紀，我們找到正確平衡的能力，並沒有比石器時代的祖先高明多少。儘管谷歌(Google)和臉書(Facebook)的使命宣言百般暗示，資訊技術變快、變有效率，不一定會讓世界更美好，只會讓我們更迫切需要在真相與秩序之間取得平衡。人類在數萬年前發明虛構故事時就學過這個教訓。當人類發明第二項偉大的資訊技術，也就是**書面文件**時，同樣的教訓將再次上演（見第3章）。"
     ]
    }
