      "西元前一千年間，猶太先知、祭司與學者寫下大量故事、預言、詩歌與編年史，但聖經時代並沒有定於一尊的經典——大衛王或先知以賽亞都沒見過《希伯來聖經》。常有人誤以為最早的版本來自[[死海古卷|Dead Sea Scrolls]]：這批在昆蘭（Qumran）附近洞穴發現、多寫於西元前最後兩世紀的約九百份文獻，多數學者認為是某猶太教派的檔案庫。但古卷中並沒有一本《希伯來聖經》，也沒有古卷指出二十四卷書屬於同一個資料集。有十九份古卷保存〈創世記〉，卻也有二十多份保存非正典的〈以諾書〉；昆蘭的猶太人顯然同樣重視兩者。",
