      "約西費斯庫 (Gheorghe Iosifescu) 是羅馬尼亞第一批電腦科學家。1970年代電腦初引進時，當局對這種陌生的資訊科技極度不安。1976年某天，他走進政府計算中心上班，發現一個穿著皺巴巴西裝的陌生男人坐在那裡；打招呼不回、自我介紹也不吭聲。等他把大型電腦開機工作，那人就拉椅子靠過來，盯著他的一舉一動，默默在小記事本上做筆記，下班時連道別都沒有。約西費斯庫很清楚最好別問——那是令人聞風喪膽的祕密警察「國安局」(Securitate) 特工。隔天一早，特工又已經到了。這樣持續了**十三年**，直到1989年共產政權垮臺，他始終不知道對方叫什麼名字。",
