      "然而齊奧塞斯庫就像他看齊的史達林，不可能一天二十四小時監控所有公民。特工也得睡覺：若真要全天候盯住兩千萬人，大概需要**四千萬名特工**，而國安局實際只有約四萬人。就算真能召喚出四千萬名特工，也會冒出新問題：誰來監控特工？獨裁者比誰都更不信任自己的特工與官員——尤其在間諜頭子帕切帕 (Ion Mihai Pacepa) 1978年叛逃美國之後，政治局委員、高階官員、軍隊將領與國安局主管受到的監控，比約西費斯庫更嚴密。祕密警察越壯大，就得派出更多特工去監視特工。",
